import{_ as r,C as s,o as n,c as p,ag as i,E as o,j as e,a}from"./chunks/framework.DUTPmUpA.js";const u="/_assets/ViSMwvo.CJdjBBpo.jpg",m="/_assets/4UyiXu4.DblKaNuo.jpg",d="/_assets/LMMyBO8.DFnfewAq.jpg",c="/_assets/YRYNesy.Co85JLlX.jpg",g="/_assets/z7Et01i.vNlnMS3X.jpg",h="/_assets/aSymXLa.RumDI1m5.jpg",_="/_assets/jIhkOve.cr6LmFyp.jpg",f="/_assets/UnkemptFarawayGossamerwingedbutterfly.XvTEAVky.mp4",x="/_assets/PowerfulBlueBilby.BoSSHf6A.mp4",b="/_assets/SkeletalEmptyArieltoucan.CZSGp5Uk.mp4",T="/_assets/lfiWxVo.DTnzFuxj.jpg",S="/_assets/UtssvMq.DjOHWylk.jpg",q="/_assets/1rg3eDr.CcIkjsEk.jpg",B="/_assets/0Syq2Lb.CAGsS60z.jpg",N=JSON.parse('{"title":"Эффекты статуса","description":"","frontmatter":{"title":"Эффекты статуса","author":"TheRisen41","steamId":"76561198078268404","date":"09.10.2016"},"headers":[],"relativePath":"assets/particles/status-effects.md","filePath":"assets/particles/status-effects.md"}'),D={name:"assets/particles/status-effects.md"};function k(P,l,F,j,C,E){const t=s("StaticVideo");return n(),p("div",null,[l[0]||(l[0]=i('<h1 id="эффекты-статуса" tabindex="-1">Эффекты статуса <a class="header-anchor" href="#эффекты-статуса" aria-label="Permalink to &quot;Эффекты статуса&quot;">​</a></h1><p>Это базовое руководство о том, как создавать/изменять частицы эффекта статуса в редакторе частиц. Это мой первый урок, поэтому любые отзывы приветствуются. Файл шаблона находится в нижней части руководства, если вы хотите быстро создать эффект статуса.</p><h2 id="что-такое-эффект-статуса" tabindex="-1">Что такое эффект статуса? <a class="header-anchor" href="#что-такое-эффект-статуса" aria-label="Permalink to &quot;Что такое эффект статуса?&quot;">​</a></h2><p>Статусные эффекты — это частицы, изменяющие текстуру поверхности и ее параметры модели. Они отличаются от обычных частиц тем, что не нуждаются в излучателе и в основном используются для баффов/дебаффов и создания чучел.</p><p><strong>Примеры:</strong></p><p><img src="'+u+'" alt="/images/external/ViSMwvo.jpg"><img src="'+m+'" alt="/images/external/4UyiXu4.jpg"><br><img src="'+d+'" alt="/images/external/LMMyBO8.jpg"><br><img src="'+c+'" alt="/images/external/YRYNesy.jpg"><br><img src="'+g+'" alt="/images/external/z7Et01i.jpg"></p><h2 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to &quot;Начало работы&quot;">​</a></h2><p>Создайте новый файл в редакторе частиц и сохраните его. Прежде чем начать, убедитесь, что вы включили «<strong>просмотр как эффект статуса DOTA</strong>» в редакторе частиц на вкладке «Вид». Это важно, иначе вы не сможете понять никакого смысла в функциях.</p><p>Что вам нужно для базового эффекта статуса:</p><ul><li><p><strong>Рендереры:</strong></p><ul><li>Эффект статуса рендеринга</li></ul></li><li><p><strong>Операторы:</strong></p><ul><li>Срок службы ограничен по времени.</li></ul></li><li><p><strong>Инициализаторы:</strong></p><ul><li>9x скалярный случайный</li><li>8 случайных векторных компонентов или 3 случайных векторных компонента</li><li>2 случайных цвета</li></ul></li></ul><p><strong><em>Вот как в итоге должно выглядеть окно функций при использовании «Случайного векторного компонента» (порядок не важен):</em></strong><img src="'+h+'" alt="/images/external/aSymXLa.jpg"></p><h2 id="шаг-за-шагом" tabindex="-1">Шаг за шагом <a class="header-anchor" href="#шаг-за-шагом" aria-label="Permalink to &quot;Шаг за шагом&quot;">​</a></h2><p><em>Примечание:</em> Поскольку я не слишком опытен в моделировании и текстурировании, я не могу точно сказать, какой тип текстуры или параметр что делает, но я могу показать вам, как это изменить.<br> Также обратите внимание, что ваш эффект статуса не будет виден в редакторе частиц. Чтобы увидеть это, вам придется зайти в игру.</p><h3 id="базовые-своиства" tabindex="-1">Базовые свойства <a class="header-anchor" href="#базовые-своиства" aria-label="Permalink to &quot;Базовые свойства&quot;">​</a></h3><p>В базовых свойствах установите начальные частицы и максимальное количество частиц равными 1. Остальное оставьте как есть.</p><h3 id="срок-службы-ограничен-по-времени" tabindex="-1">Срок службы ограничен по времени <a class="header-anchor" href="#срок-службы-ограничен-по-времени" aria-label="Permalink to &quot;Срок службы ограничен по времени&quot;">​</a></h3><p>Просто оставьте это как есть.</p><h3 id="эффект-статуса-рендеринга" tabindex="-1">Эффект статуса рендеринга <a class="header-anchor" href="#эффект-статуса-рендеринга" aria-label="Permalink to &quot;Эффект статуса рендеринга&quot;">​</a></h3><p>Эта функция будет иметь наибольшее влияние на внешний вид эффекта статуса. Он выбирает, какой тип текстуры каким файлом <code>.vtex</code>/<code>.vmat</code> заменяется. В эффектах статуса Valve эти текстуры определяются с помощью нескольких «случайных векторных компонентов». По сути, они делают то же самое, но мы выбираем «Эффект статуса рендеринга», потому что с ним гораздо проще обращаться и понимать.</p><p><img src="'+_+'" alt="/images/external/jIhkOve.jpg"></p><p><em>Примечание:</em> Наибольшее влияние, вероятно, окажут следующие: текстура деформации цвета и текстура детализации 2.</p><h4 id="цветовая-деформация-текстуры" tabindex="-1">Цветовая деформация текстуры <a class="header-anchor" href="#цветовая-деформация-текстуры" aria-label="Permalink to &quot;Цветовая деформация текстуры&quot;">​</a></h4><p>3D-текстура, которая применяет преобразование цвета, например сдвиг оттенка или настройку контрастности, к исходным цветам. Нажмите на увеличительное стекло и введите «Цветовая деформация» в строке поиска, чтобы увидеть все текстуры цветовой деформации.</p><p><em>Примечание:</em> Для этого подойдут только текстуры с цветовой деформацией.</p><p>Результаты с различными текстурами Colorwarp:</p>',25)),o(t,{path:f}),l[1]||(l[1]=e("p",null,[e("em",null,"Связанные параметры"),a(":")],-1)),l[2]||(l[2]=e("ul",null,[e("li",null,"ColorWarpBlendFactor")],-1)),l[3]||(l[3]=e("h4",{id:"деталь-2-текстуры",tabindex:"-1"},[a("Деталь 2 текстуры "),e("a",{class:"header-anchor",href:"#деталь-2-текстуры","aria-label":'Permalink to "Деталь 2 текстуры"'},"​")],-1)),l[4]||(l[4]=e("p",null,[a("Текстура, которая неоднократно накладывается на модель. Для этого вы можете использовать любую текстуру. Вы даже можете использовать свои собственные (просто посмотрите, как конвертировать .tga в .vtex в Google). Убедитесь, что вы выбрали подходящий режим наложения для вашей текстуры с помощью "),e("strong",null,"D_DETAIL_2"),a(" (о нем будет рассказано позже). Если вам это не нужно, установите для Detail2BlendFactor значение 0.")],-1)),l[5]||(l[5]=e("p",null,"Результаты с различными текстурами Detail 2 (режим наложения: 5):",-1)),o(t,{path:x}),l[6]||(l[6]=i('<p><em>Связанные параметры</em>:</p><ul><li>Detail2BlendFactor</li><li>D_DETAIL_2</li><li>Detail2TexCoordScale</li></ul><h4 id="диффузная-текстура-деформации" tabindex="-1">Диффузная текстура деформации <a class="header-anchor" href="#диффузная-текстура-деформации" aria-label="Permalink to &quot;Диффузная текстура деформации&quot;">​</a></h4><p>Определяет места возникновения диффузных отражений. Это по большей части устарело, поскольку не включено у большинства героев. Если вам это не нужно, установите для DiffuseWarpBlendToFull значение 0.</p><p><em>Связанные параметры</em>:</p><ul><li>DiffuseWarpBlendToFull</li></ul><h4 id="текстура-деформации-цвета-по-френелю" tabindex="-1">Текстура деформации цвета по Френелю <a class="header-anchor" href="#текстура-деформации-цвета-по-френелю" aria-label="Permalink to &quot;Текстура деформации цвета по Френелю&quot;">​</a></h4><p>Применяет преобразование цвета по краям модели. Используйте для этого текстуры деформации цвета.</p><p><em>Примечание</em>: Вам это не обязательно.</p><h4 id="текстура-деформации-френеля" tabindex="-1">Текстура деформации Френеля <a class="header-anchor" href="#текстура-деформации-френеля" aria-label="Permalink to &quot;Текстура деформации Френеля&quot;">​</a></h4><p>Определяет, где применяется цветовая деформация Френеля.</p><h4 id="зеркальная-текстура-деформации" tabindex="-1">Зеркальная текстура деформации <a class="header-anchor" href="#зеркальная-текстура-деформации" aria-label="Permalink to &quot;Зеркальная текстура деформации&quot;">​</a></h4><p>Определяет, где происходит зеркальное отражение. Зеркальное отражение – это зеркальное отражение Света. Если вам это не нужно, установите SpecularScale в 0. Результаты с разным количеством зеркального отражения:</p>',13)),o(t,{path:b}),l[7]||(l[7]=i('<p><em>Связанные параметры</em>:</p><ul><li>Зеркальный цвет</li><li>Зеркальная шкала</li><li>Зеркальная экспонента</li><li>SpecularExComponentBlendToFull</li><li>SpecularBlendToFull</li></ul><h4 id="текстура-карты-окружающеи-среды" tabindex="-1">Текстура карты окружающей среды <a class="header-anchor" href="#текстура-карты-окружающеи-среды" aria-label="Permalink to &quot;Текстура карты окружающей среды&quot;">​</a></h4><p>Я не уверен, что это делает. Кажется, это не имеет большого влияния.</p><h3 id="скалярныи-случаиныи" tabindex="-1">Скалярный случайный <a class="header-anchor" href="#скалярныи-случаиныи" aria-label="Permalink to &quot;Скалярный случайный&quot;">​</a></h3><p>В окне свойств вы можете установить, что должна делать скалярная случайная функция. Поле вывода определяет, какой параметр следует изменить, а минимальное и максимальное значения (которые в большинстве случаев должны быть равными) определяют степень изменения.</p><p><img src="'+T+'" alt="/images/external/lfiWxVo.jpg"></p><p><strong><em>Для нашего 9-скалярного случайного числа нам нужно:</em></strong><em>Примечание</em>: В этом руководстве минимум и максимум всегда будут равны. Если вы не знаете, что происходит, просто поиграйте со значениями и наблюдайте за изменениями в игре.</p><ul><li><strong>ColorWarpBlendFactor</strong><ul><li>Определяет степень применения текстуры цветовой деформации.</li><li><em>Значения</em>: 1 = полностью применено, 0 = полностью игнорируется.</li></ul></li><li><strong>D_DETAIL_2</strong><ul><li>Метод смешивания текстуры детали 2. (Некоторые из них: Add, Add SelfIllum, Mod2X)</li><li><em>Значения</em>: от 0 до 5 в целых числах.</li></ul></li><li><strong>Detail2TexCoordScale</strong> — Устанавливает масштаб координат текстуры Detail2. <ul><li><em>Значения</em>: от 0 до 8. Чем больше число, тем меньше текстура Detail2 и тем чаще ее необходимо размещать на модели. Типичные значения: 2-5.</li></ul></li><li><strong>Detail2BlendFactor</strong><ul><li>Определяет, насколько сильно смешивается текстура Detail2.</li><li><em>Значения</em>: 1 = Полностью сливается, 0 = Полностью прозрачно, также может быть &gt;1.</li></ul></li><li><strong>CubeMapScalar</strong><ul><li>Множитель, управляющий общей интенсивностью карты куба. Вам не нужно знать, что именно это делает, поскольку, похоже, это не оказывает большого влияния.</li><li><em>Значения</em>: от 0 до 20.</li></ul></li><li><strong>Амбиентная шкала</strong><ul><li>Устанавливает интенсивность применения окружающего освещения.</li><li><em>Значения</em>: при более высоких значениях окружающее освещение будет выглядеть сильнее.</li></ul></li><li><strong>RimLightScale</strong><ul><li>Устанавливает интенсивность отображения ободного света. Rim Light — подсветка по краям модели.</li><li><em>Значения</em>: от 0 до 100. Большие значения сделают Rim Light более сильным.</li></ul></li><li><strong>НЕТ($RIMLIGHTBLENDTOFULL)</strong><ul><li>Определяет, насколько сильно смешивается Rim Light. (Я не уверен в этом)</li><li><em>Значения</em>: от 0 до 1.</li></ul></li><li><strong>НЕТ($FRESNELCOLORWARPBLENDTOFULL)</strong><ul><li>Определяет, насколько сильно смешивается текстура Fresnel Colorwarp. (Я не уверен в этом)</li><li><em>Значения</em>: от 0 до 1.</li></ul></li></ul><h3 id="случаиныи-векторныи-компонент-случаиныи-вектор" tabindex="-1">Случайный векторный компонент/Случайный вектор <a class="header-anchor" href="#случаиныи-векторныи-компонент-случаиныи-вектор" aria-label="Permalink to &quot;Случайный векторный компонент/Случайный вектор&quot;">​</a></h3><p><em>Примечание</em>: вы можете использовать либо 8 <em>случайных векторных компонентов</em>, либо 3 <em>случайных векторных компонента</em>.</p><h4 id="компонент-вектора-случаиныи" tabindex="-1">Компонент вектора случайный <a class="header-anchor" href="#компонент-вектора-случаиныи" aria-label="Permalink to &quot;Компонент вектора случайный&quot;">​</a></h4><p>Здесь функциональность определяется через поле вывода и поле компонента. Поле вывода выбирает набор из трех разных параметров (как вы можете видеть, некоторые из них могут иметь значение NONE и являются просто заполнителями). Поле компонента выбирает, какой именно параметр из этого набора следует изменить. Компонент X выбирает первый, Компонент Y — второй, а Компонент Z — третий. Как и в случае со скалярными случайными значениями min и max, определяют степень изменения параметра.</p><p><img src="'+S+'" alt="/images/external/UtssvMq.jpg"></p><h4 id="вектор-случаиныи" tabindex="-1">Вектор случайный <a class="header-anchor" href="#вектор-случаиныи" aria-label="Permalink to &quot;Вектор случайный&quot;">​</a></h4><p>Имеет ту же цель, что и <em>Векторный компонент случайный</em>, но здесь вы можете редактировать все 3 параметра набора в одной функции. Первые минимальные и максимальные значения задают минимальные и максимальные значения для первого параметра выбранного набора, вторые минимальные и максимальные значения задают значения для второго параметра и так далее. Если вам не нужен параметр, установите его минимальное и максимальное значения на 0 или -1.</p><p><img src="'+q+'" alt="/images/external/1rg3eDr.jpg"></p><p>**_Для наших случайных 8 векторных компонентов или случайных 3 векторных компонентов нам нужно: _ ** <em>Примечание</em>: Опять же, просто поиграйте со значениями, чтобы увидеть, что изменилось.<br> С <em>Vector random</em> вам понадобится только один из каждого набора.</p><h4 id="_2x-1x-specularscale-none-diffusewarpblendtofull" tabindex="-1">2x/1x SpecularScale +NONE+DiffuseWarpBlendToFull <a class="header-anchor" href="#_2x-1x-specularscale-none-diffusewarpblendtofull" aria-label="Permalink to &quot;2x/1x SpecularScale +NONE+DiffuseWarpBlendToFull&quot;">​</a></h4><ul><li><p><strong>Зеркальная шкала</strong></p><ul><li>Устанавливает, насколько сильно видно зеркальное отражение.</li><li><em>Значения</em>: от 0 до 1000. Большие значения приводят к более сильному зеркальному отражению. Обычно: от 0 до 100.</li></ul></li><li><p><strong>DiffuseWarpBlendToFull</strong></p><ul><li>Определяет степень смешивания текстуры диффузной деформации.</li><li><em>Значения</em>: 1 = Полностью сливается, 0 = Полностью прозрачно.</li></ul></li></ul><h4 id="_3x-1x-specularexcomponent-specularexcomponentblendtofull-specularblendtofull" tabindex="-1">3x/1x SpecularExComponent+SpecularExComponentBlendToFull+SpecularBlendToFull <a class="header-anchor" href="#_3x-1x-specularexcomponent-specularexcomponentblendtofull-specularblendtofull" aria-label="Permalink to &quot;3x/1x SpecularExComponent+SpecularExComponentBlendToFull+SpecularBlendToFull&quot;">​</a></h4><ul><li><p><strong>Зеркальная экспонента</strong></p><ul><li>Устанавливает размер Specular Highlight Spot.</li><li><em>Значения</em>: от 1 до 512. Обычно от 5 до 20.</li></ul></li><li><p><strong>SpecularExComponentBlendToFull</strong></p><ul><li>Определяет степень смешивания показателя зеркального отражения.</li><li><em>Значения</em>: 1 = Полностью сливается, 0 = Полностью прозрачно.</li></ul></li><li><p><strong>SpecularBlendToFull</strong></p><ul><li>Определяет степень смешивания Specular.</li><li><em>Значения</em>: 1 = Полностью сливается, 0 = Полностью прозрачно.</li></ul></li></ul><h4 id="_3x-1x-reflectionstintbaseblendtonone-metalnessblendtofull-selfillumblendtofull" tabindex="-1">3x/1x ReflectionsTintBaseBlendToNone+MetalnessBlendToFull+SelfIllumBlendToFull <a class="header-anchor" href="#_3x-1x-reflectionstintbaseblendtonone-metalnessblendtofull-selfillumblendtofull" aria-label="Permalink to &quot;3x/1x ReflectionsTintBaseBlendToNone+MetalnessBlendToFull+SelfIllumBlendToFull&quot;">​</a></h4><ul><li><p><strong>ReflectionsTintBaseBlendToNone</strong></p><ul><li>Я не уверен в этом, но это как-то связано с зеркальным отражением.</li><li><em>Значения</em>: от 0 до 1. Большие значения сделают зеркальное отражение более сильным.</li></ul></li><li><p><strong>MetalnessBlendToFull</strong></p><ul><li>Определяет, насколько металлическим будет эффект статуса.</li><li><em>Значения</em>: 0 = нет металличности, 1 = полная металличность.</li></ul></li><li><p><strong>SelfIllumBlendToFull</strong></p><ul><li>Устанавливает степень самоподсветки эффекта статуса.</li><li><em>Значения</em>: 0 = самоподсветка отсутствует, 1 = самоподсветка полностью.</li></ul></li></ul><h3 id="цвет-случаиныи" tabindex="-1">Цвет случайный <a class="header-anchor" href="#цвет-случаиныи" aria-label="Permalink to &quot;Цвет случайный&quot;">​</a></h3><p>С помощью функции «Случайный цвет» мы можем определить цвет окружающего света и зеркальный цвет. Единственные параметры, которые нам нужны в окне свойств, — это цвет 1, цвет 2 и поле вывода. В поле вывода снова указывается, что будет изменено, а для цвета 1 и 2 задан цвет, который будет изменен.</p><p><img src="'+B+'" alt="/images/external/0Syq2Lb.jpg"><strong><em>Для наших двух случайных цветов нам нужно:</em></strong></p><p><em>Примечание</em>: Цвет 1 и 2 не обязательно должны быть одинаковыми, но в большинстве случаев они должны быть одинаковыми.</p><ul><li><p><strong>RimLightColor</strong></p><ul><li>Устанавливает цвет обода.</li></ul></li><li><p><strong>ЗеркальныйЦвет</strong></p><ul><li>Устанавливает зеркальный цвет.</li></ul></li></ul><h2 id="шаблон" tabindex="-1">Шаблон <a class="header-anchor" href="#шаблон" aria-label="Permalink to &quot;Шаблон&quot;">​</a></h2><p>Здесь вы можете скачать шаблон базового файла частиц с эффектом статуса:<br><a href="https://dl.dropboxusercontent.com/u/32606308/status_effect_template.vpcf" target="_blank" rel="noreferrer">https://dl.dropboxusercontent.com/u/32606308/status_effect_template.vpcf</a> (щелкните правой кнопкой мыши -&gt; сохранить цель как)<br> Обязательно поместите его в папку <strong>content</strong> вашего дополнения.</p><p>Вы можете просто отредактировать текстуру <em>colorwarp</em> и <em>detail 2</em>, чтобы получить быстрые результаты. Убедитесь, что вы выбрали подходящий режим наложения с помощью <strong>D_DETAIL_2</strong> для вашей текстуры <em>detail 2</em> и используйте соответствующую текстуру <em>colorwarp</em> (как упоминалось выше).</p>',32))])}const A=r(D,[["render",k]]);export{N as __pageData,A as default};
